{
  "name": "opencode-web-plugin",
  "version": "0.1.1",
  "description": "Multi-provider web search and content fetching for OpenCode v2",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "prepack": "bun run build",
    "release:patch": "bash scripts/release.sh patch",
    "release:minor": "bash scripts/release.sh minor",
    "release:major": "bash scripts/release.sh major"
  },
  "keywords": [
    "opencode",
    "plugin",
    "web-search",
    "tavily",
    "exa",
    "jina"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AnotiaWang/opencode-web-plugin.git"
  },
  "bugs": {
    "url": "https://github.com/AnotiaWang/opencode-web-plugin/issues"
  },
  "homepage": "https://github.com/AnotiaWang/opencode-web-plugin#readme",
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "engines": {
    "node": ">=20"
  },
  "dependencies": {
    "@opencode-ai/plugin": "next"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "latest"
  }
}

import { Plugin } from "@opencode-ai/plugin"
import { resolveConfig } from "./config/resolve.js"
import { createFetchTool } from "./tools/fetch.js"
import { createSearchTool } from "./tools/search.js"

export { resolveConfig } from "./config/resolve.js"
export type { JinaRegion, WebPluginConfig, WebPluginOptions } from "./config/schema.js"
export { WebPluginError } from "./errors/index.js"
export type { WebPluginErrorCode } from "./errors/index.js"
export type {
  Capability,
  FetchRequest,
  FetchResponse,
  ProviderDefinition,
  ProviderID,
  SearchRequest,
  SearchResponse,
  SearchResult,
} from "./providers/types.js"

export default Plugin.define({
  id: "opencode.web",
  setup: async (ctx) => {
    const config = resolveConfig(ctx.options)
    await ctx.tool.transform((tools) => {
      tools.add(createSearchTool(config))
      tools.add(createFetchTool(config))
    })
  },
})
